import { describe, test, expect, beforeEach } from 'bun:test';
import { ClaudeEventProcessor } from './ClaudeEventProcessor';
import type { ClaudeHookInput } from './types';
import testFixtures from '../../../test-data/claude-test-fixtures.json';

describe('ClaudeEventProcessor', () => {
  let processor: ClaudeEventProcessor;

  beforeEach(() => {
    processor = new ClaudeEventProcessor();
  });

  describe('normalize()', () => {
    describe('PreToolUse events', () => {
      test('should normalize PreToolUse event with Read tool', () => {
        const input = testFixtures.claude.preToolUse as ClaudeHookInput;
        const result = processor.normalize(input);

        expect(result.eventType).toBe('pre-tool-use');
        expect(result.provider).toBe('claude');
        expect(result.sessionId).toBe('e8a7d70c-f4e1-48a2-93b8-2b471c417043');
        expect(result.workingDirectory).toBe('/Users/griever/Developer/build-stuff/monorepo/electron-react');
        expect(result.toolName).toBe('Read');
        expect(result.toolInput).toEqual({
          file_path: '/Users/griever/Developer/build-stuff/monorepo/electron-react/.erb/scripts/delete-source-maps.js'
        });
        expect(result.rawFilePaths).toEqual([
          '/Users/griever/Developer/build-stuff/monorepo/electron-react/.erb/scripts/delete-source-maps.js'
        ]);
        expect(result.operation).toBe('read');
      });

      test('should normalize PreToolUse with Edit tool', () => {
        const input = testFixtures.claude.tools.edit as ClaudeHookInput;
        const result = processor.normalize(input);

        expect(result.eventType).toBe('pre-tool-use');
        expect(result.toolName).toBe('Edit');
        expect(result.operation).toBe('edit');
        expect(result.rawFilePaths).toBeDefined();
        expect(result.rawFilePaths).toContain(testFixtures.claude.tools.edit.tool_input.file_path);
      });

      test('should normalize PreToolUse with Bash tool', () => {
        const input = testFixtures.claude.tools.bash as ClaudeHookInput;
        const result = processor.normalize(input);

        expect(result.eventType).toBe('pre-tool-use');
        expect(result.toolName).toBe('Bash');
        expect(result.toolInput).toBeDefined();
      });

      test('should normalize PreToolUse with Grep tool', () => {
        const input = testFixtures.claude.tools.grep as ClaudeHookInput;
        const result = processor.normalize(input);

        expect(result.eventType).toBe('pre-tool-use');
        expect(result.toolName).toBe('Grep');
        expect(result.operation).toBe('search');

        if (input.tool_input?.path) {
          expect(result.rawFilePaths).toContain(input.tool_input.path);
        }
      });

      test('should normalize PreToolUse with Glob tool', () => {
        const input = testFixtures.claude.tools.glob as ClaudeHookInput;
        const result = processor.normalize(input);

        expect(result.eventType).toBe('pre-tool-use');
        expect(result.toolName).toBe('Glob');
        expect(result.operation).toBeUndefined();
      });

      test('should normalize PreToolUse with TodoWrite tool', () => {
        const input = testFixtures.claude.tools.todoWrite as ClaudeHookInput;
        const result = processor.normalize(input);

        expect(result.eventType).toBe('pre-tool-use');
        expect(result.toolName).toBe('TodoWrite');
        expect(result.toolInput).toBeDefined();
      });
    });

    describe('PostToolUse events', () => {
      test('should normalize PostToolUse event with tool response', () => {
        const input = testFixtures.claude.postToolUse as ClaudeHookInput;
        const result = processor.normalize(input);

        expect(result.eventType).toBe('post-tool-use');
        expect(result.provider).toBe('claude');
        expect(result.toolName).toBe('Read');
        expect(result.toolInput).toBeDefined();
        expect(result.toolOutput).toBeDefined();
        expect(result.rawFilePaths).toEqual([
          '/Users/griever/Developer/build-stuff/monorepo/electron-react/.erb/scripts/delete-source-maps.js'
        ]);
      });

      test('should extract file paths from Glob output', () => {
        const globPostToolUse = {
          ...testFixtures.claude.tools.glob,
          hook_event_name: 'PostToolUse',
          tool_response: [
            '/path/to/file1.ts',
            '/path/to/file2.ts',
            '/path/to/file3.ts'
          ]
        } as ClaudeHookInput;

        const result = processor.normalize(globPostToolUse);
        expect(result.eventType).toBe('post-tool-use');
        expect(result.rawFilePaths).toContain('/path/to/file1.ts');
        expect(result.rawFilePaths).toContain('/path/to/file2.ts');
        expect(result.rawFilePaths).toContain('/path/to/file3.ts');
      });

      test('should extract file paths from Grep output (string format)', () => {
        const grepPostToolUse = {
          ...testFixtures.claude.tools.grep,
          hook_event_name: 'PostToolUse',
          tool_response: '/path/to/file1.ts:10:const result = true;\n/path/to/file2.ts:20:export default result;'
        } as ClaudeHookInput;

        const result = processor.normalize(grepPostToolUse);
        expect(result.eventType).toBe('post-tool-use');
        expect(result.rawFilePaths).toContain('/path/to/file1.ts');
        expect(result.rawFilePaths).toContain('/path/to/file2.ts');
      });
    });

    describe('Notification events', () => {
      test('should normalize Notification event', () => {
        const input = testFixtures.claude.notification as ClaudeHookInput;
        const result = processor.normalize(input);

        expect(result.eventType).toBe('notification');
        expect(result.provider).toBe('claude');
        expect(result.data).toBeDefined();
        expect(result.data?.message).toBe('Claude needs your permission to use Update');
      });
    });

    describe('Stop events', () => {
      test('should normalize Stop event', () => {
        const input = testFixtures.claude.stop as ClaudeHookInput;
        const result = processor.normalize(input);

        expect(result.eventType).toBe('stop');
        expect(result.provider).toBe('claude');
        expect(result.sessionId).toBe('f5faec2e-1b76-4361-aeab-8aeecfefcf0d');
        expect(result.data?.stopHookActive).toBe(false);
      });

      test('should normalize SubagentStop event', () => {
        const input = testFixtures.claude.subagentStop as ClaudeHookInput;
        const result = processor.normalize(input);

        expect(result.eventType).toBe('subagent-stop');
        expect(result.provider).toBe('claude');
      });
    });

    describe('Edge cases', () => {
      test('should handle MCP tool events', () => {
        if (testFixtures.claude.edgeCases?.mcpTool) {
          const input = testFixtures.claude.edgeCases.mcpTool as ClaudeHookInput;
          const result = processor.normalize(input);

          expect(result.eventType).toBeDefined();
          expect(result.provider).toBe('claude');
          expect(result.toolName).toContain('mcp__');
        }
      });

      test('should handle missing working directory', () => {
        if (testFixtures.claude.edgeCases?.noWorkingDir) {
          const input = testFixtures.claude.edgeCases.noWorkingDir as ClaudeHookInput;
          const result = processor.normalize(input);

          expect(result.workingDirectory).toBeDefined();
          expect(result.provider).toBe('claude');
        }
      });

      test('should handle events without session_id gracefully', () => {
        const input = {
          hook_event_name: 'PreToolUse',
          tool_name: 'Read',
          tool_input: { file_path: '/test/file.ts' },
          cwd: '/test',
          transcript_path: '/test/transcript.jsonl'
        } as ClaudeHookInput;

        const result = processor.normalize(input);
        expect(result.sessionId).toBe('');
        expect(result.eventType).toBe('pre-tool-use');
      });

      test('should handle unknown event types', () => {
        const input = {
          hook_event_name: 'UnknownEventType',
          session_id: 'test-session',
          cwd: '/test'
        } as any;

        const result = processor.normalize(input);
        expect(result.eventType).toBe('unknown');
        expect(result.provider).toBe('claude');
      });

      test('should handle legacy claude_stop_hook format', () => {
        const input = {
          hook_event_name: 'claude_stop_hook',
          session_id: 'test-session',
          transcript_path: '/test/transcript.jsonl',
          cwd: '/test'
        } as ClaudeHookInput;

        const result = processor.normalize(input);
        expect(result.eventType).toBe('stop');
      });
    });

    describe('File path extraction', () => {
      test('should extract multiple file paths from MultiEdit tool', () => {
        const multiEditInput = {
          session_id: 'test',
          transcript_path: '/test/transcript.jsonl',
          cwd: '/test',
          hook_event_name: 'PreToolUse',
          tool_name: 'MultiEdit',
          tool_input: {
            file_path: '/test/main.ts',
            edits: [
              { old_string: 'foo', new_string: 'bar' },
              { old_string: 'baz', new_string: 'qux' }
            ]
          }
        } as ClaudeHookInput;

        const result = processor.normalize(multiEditInput);
        expect(result.rawFilePaths).toContain('/test/main.ts');
        expect(result.operation).toBe('edit');
      });

      test('should handle relative paths in tool input', () => {
        const relativePathInput = {
          session_id: 'test',
          transcript_path: '/test/transcript.jsonl',
          cwd: '/project/root',
          hook_event_name: 'PreToolUse',
          tool_name: 'Read',
          tool_input: {
            file_path: './src/index.ts'
          }
        } as ClaudeHookInput;

        const result = processor.normalize(relativePathInput);
        expect(result.rawFilePaths).toContain('./src/index.ts');
      });

      test('should deduplicate file paths', () => {
        const duplicatePathInput = {
          session_id: 'test',
          transcript_path: '/test/transcript.jsonl',
          cwd: '/test',
          hook_event_name: 'PostToolUse',
          tool_name: 'Grep',
          tool_input: { path: '/test/file.ts', pattern: 'test' },
          tool_response: '/test/file.ts:1:test\n/test/file.ts:2:test\n/test/file.ts:3:test'
        } as ClaudeHookInput;

        const result = processor.normalize(duplicatePathInput);
        expect(result.rawFilePaths).toHaveLength(1);
        expect(result.rawFilePaths).toContain('/test/file.ts');
      });
    });
  });

  describe('extractToolInfo()', () => {
    test('should extract tool info from event with tool_name', () => {
      const event = {
        tool_name: 'Read',
        tool_input: { file_path: '/test/file.ts' }
      };

      const result = processor.extractToolInfo(event);
      expect(result).toBeDefined();
      expect(result?.toolName).toBe('Read');
      expect(result?.toolInput).toEqual({ file_path: '/test/file.ts' });
    });

    test('should return null for event without tool_name', () => {
      const event = {
        hook_event_name: 'Notification',
        message: 'Test message'
      };

      const result = processor.extractToolInfo(event);
      expect(result).toBeNull();
    });
  });
});